typedef struct {unsigned calls,guards,sends;unsigned long long time;int guard_failure,failed_send,failed_cleanup;unsigned slow_guard;char sent[8];} fake;
static unsigned long long now(void *p){fake*f=p;f->calls++;return f->time;}
static void sleep_ms(void *p,unsigned ms){fake*f=p;f->calls++;f->time+=ms;}
static int guard(void *p){fake*f=p;f->calls++;f->guards++;f->time+=f->slow_guard;return !f->guard_failure || f->guards<(unsigned)f->guard_failure;}
static int send_ev(void *p,int dx,int dy,int b){fake*f=p;(void)dx;(void)dy;f->calls++;f->sends++;if(f->sends<=8)f->sent[f->sends-1]=(char)b;return (f->failed_send==(int)f->sends || f->failed_cleanup==(int)f->sends)?0:1;}
static void reset(fake*f,wh_backend*b){memset(f,0,sizeof *f);b->ctx=f;b->now_ms=now;b->sleep_ms=sleep_ms;b->guard=guard;b->send=send_ev;}
