 reset(&f,&b);f.guard_failure=1;C(wh_run(&p,&b,0,&result)==WH_E_GUARD);C(f.sends==0&&!result.release_owed);
 reset(&f,&b);f.guard_failure=2;C(wh_run(&p,&b,0,&result)==WH_E_GUARD);C(f.sends==1&&result.release_owed&&result.cleanup_tried==0);
 reset(&f,&b);f.failed_send=1;C(wh_run(&p,&b,0,&result)==WH_E_API);C(f.sends==2&&f.sent[1]=='U'&&!result.release_owed&&result.delivered==1);
 reset(&f,&b);f.failed_send=1;f.failed_cleanup=2;C(wh_run(&p,&b,0,&result)==WH_E_API);C(f.sends==2&&result.release_owed&&result.delivered==0);
 reset(&f,&b);f.failed_send=2;f.guard_failure=3;C(wh_run(&p,&b,0,&result)==WH_E_API);C(f.sends==2&&f.sent[1]=='N'&&result.release_owed&&result.cleanup_tried==1);
 reset(&f,&b);f.slow_guard=31000;C(wh_run(&p,&b,0,&result)==WH_E_DEADLINE);C(f.sends==0&&!result.release_owed);
 reset(&f,&b);p.rows[0].dx=99;C(wh_run(&p,&b,0,&result)!=0);C(f.calls==0);p.rows[0].dx=0;
 p.rows[1].delay=1001;C(wh_run(&p,&b,1,&result)!=0);C(f.calls==0);p.rows[1].delay=20;
